import { useEffect, useState } from 'react';
import {
  JxBadge,
  JxDivider,
  JxSelect,
  JxSlider,
  JxSwitch,
  JxToggle,
} from '@jinx-ui/react';

type ThemeMode = 'dark' | 'light' | 'system';
type FontChoice = 'sans' | 'serif' | 'mono';

export interface AppearanceSettings {
  theme: ThemeMode;
  scale: number;
  dense: boolean;
  font: FontChoice;
}

const themeLabels: Record<ThemeMode, string> = {
  dark: 'Тёмная',
  light: 'Светлая',
  system: 'Системная',
};

interface AppearanceSettingsScreenProps {
  onChange?: (settings: AppearanceSettings) => void;
}

export default function AppearanceSettingsScreen({ onChange }: AppearanceSettingsScreenProps) {
  const [settings, setSettings] = useState<AppearanceSettings>({
    theme: 'system',
    scale: 100,
    dense: false,
    font: 'sans',
  });

  useEffect(() => {
    onChange?.(settings);
  }, [settings, onChange]);

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-r)' }}>
      <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
        <h2 style={{ margin: 0 }}>Внешний вид</h2>
        <JxBadge tone="accent">{themeLabels[settings.theme]}</JxBadge>
      </div>

      <JxToggle
        items={[
          { value: 'dark', label: 'Тёмная' },
          { value: 'light', label: 'Светлая' },
          { value: 'system', label: 'Системная' },
        ]}
        value={settings.theme}
        onValueChange={(value) => setSettings((prev) => ({ ...prev, theme: value as ThemeMode }))}
      />

      <JxSlider
        label="Масштаб интерфейса"
        min={80}
        max={140}
        step={5}
        unit="%"
        showOutput
        value={settings.scale}
        onValueChange={(value) => setSettings((prev) => ({ ...prev, scale: value }))}
      />

      <JxSwitch
        label="Плотная вёрстка"
        checked={settings.dense}
        onChange={(event) => setSettings((prev) => ({ ...prev, dense: event.target.checked }))}
      />

      <JxDivider label="Ещё" />

      <JxSelect
        label="Шрифт"
        options={[
          { value: 'sans', label: 'Рубленый' },
          { value: 'serif', label: 'С засечками' },
          { value: 'mono', label: 'Моноширинный' },
        ]}
        value={settings.font}
        onValueChange={(value) => setSettings((prev) => ({ ...prev, font: value as FontChoice }))}
      />
    </div>
  );
}

